[{"order":1,"type":"heading","text":"Comprehensive Testing Strategies in Next.js"},{"order":2,"type":"paragraph","text":"Building robust Next.js applications requires a multi-layered testing approach. This tutorial covers Unit and Integration testing using Jest and React Testing Library (RTL), alongside End-to-End (E2E) testing using Playwright."},{"order":3,"type":"subheading","text":"1. Setting Up Jest and React Testing Library"},{"order":4,"type":"paragraph","text":"First, install the necessary testing dependencies in your Next.js project. We need Jest, the React Testing Library, and jest-environment-jsdom."},{"order":5,"type":"code","text":"npm install --save-dev jest jest-environment-jsdom @testing-library/react @testing-library/jest-dom"},{"order":6,"type":"paragraph","text":"Create a jest.config.mjs file in the root of your Next.js project to configure Jest to work seamlessly with Next.js."},{"order":7,"type":"code","text":"import nextJest from 'next/jest.js'

const createJestConfig = nextJest({
  dir: './',
})

const customJestConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
}

export default createJestConfig(customJestConfig)"},{"order":8,"type":"paragraph","text":"Next, create the jest.setup.js file to import custom matchers from @testing-library/jest-dom."},{"order":9,"type":"code","text":"import '@testing-library/jest-dom'"},{"order":10,"type":"subheading","text":"2. Writing Component Tests with RTL"},{"order":11,"type":"paragraph","text":"Let us test a simple Counter component. Create a component at components/Counter.jsx."},{"order":12,"type":"code","text":"import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </div>
  );
}"},{"order":13,"type":"paragraph","text":"Now, write the test file components/__tests__/Counter.test.jsx."},{"order":14,"type":"code","text":"import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import Counter from '../Counter';

describe('Counter Component', () => {
  it('renders initial count and increments on click', async () => {
    render(<Counter />);

    expect(screen.getByText('Count: 0')).toBeInTheDocument();

    const button = screen.getByRole('button', { name: /increment/i });
    await userEvent.click(button);

    expect(screen.getByText('Count: 1')).toBeInTheDocument();
  });
});"},{"order":15,"type":"subheading","text":"3. Setting Up Playwright for E2E Testing"},{"order":16,"type":"paragraph","text":"End-to-end testing simulates real user scenarios across actual browsers. Install Playwright using the following command."},{"order":17,"type":"code","text":"npm init playwright@latest"},{"order":18,"type":"paragraph","text":"Create an E2E test file e2e/home.spec.ts to verify your Next.js application workflow."},{"order":19,"type":"code","text":"import { test, expect } from '@playwright/test';

test('should navigate to the about page', async ({ page }) => {
  // Start from the index page
  await page.goto('http://localhost:3000/');

  // Find an element with a link to about and click it
  await page.click('text=About');

  // The new URL should be /about
  await expect(page).toHaveURL('http://localhost:3000/about');

  // The new page should contain an h1 with "About Us"
  await expect(page.locator('h1')).toContainText('About Us');
});"},{"order":20,"type":"subheading","text":"Best Practices for Next.js Testing"},{"order":21,"type":"bullet_point","text":"Use Jest and RTL for isolated component logic, hooks, and utility functions."},{"order":22,"type":"bullet_point","text":"Mock external API requests and Next.js router features when testing components in isolation."},{"order":23,"type":"bullet_point","text":"Reserve Playwright for critical user paths, authentication flows, and multi-page integrations."},{"order":24,"type":"bullet_point","text":"Run unit tests in your CI/CD pipeline on every pull request, and E2E tests prior to deployment."}]
